      "**创建Namespace的系统调用：**",
      "//",
      "系统调用：clone()",
      "创建新进程时可以指定Namespace",
      "//",
      "用户空间代码",
      "int",
      "clone_flags",
      "=",
      "CLONE_NEWPID",
      "|",
      "//",
      "新的PID",
      "namespace",
      "CLONE_NEWNET",
      "|",
      "//",
      "新的网络namespace",
      "CLONE_NEWNS",
      "|",
      "//",
      "新的挂载namespace",
      "CLONE_NEWUTS",
      "|",
      "//",
      "新的主机名namespace",
      "CLONE_NEWIPC",
      "|",
      "//",
      "新的IPC",
      "namespace",
      "CLONE_NEWUSER;",
      "//",
      "新的用户namespace",
      "pid_t",
      "pid",
      "=",
      "clone(child_func,",
      "child_stack,",
      "clone_flags,",
      "NULL);",
      "//",
      "内核空间实现（简化版）",
      "//",
      "kernel/fork.c",
      "long",
      "do_fork(unsigned",
      "long",
      "clone_flags,",
      "...)",
      "{",
      "struct",
      "task_struct",
      "*p;",
      "//",
      "新进程",
      "//",
      "分配新进程结构体",
      "p",
      "=",
      "copy_process(clone_flags,",
      "...);",
      "//",
      "如果指定了CLONE_NEWPID，创建新的PID",
      "namespace",
      "if",
      "(clone_flags",
      "&",
      "CLONE_NEWPID)",
      "{",
      "p->nsproxy->pid_ns",
      "=",
      "create_pid_namespace(current->nsproxy->pid_ns);",
      "}",
      "//",
      "如果指定了CLONE_NEWNET，创建新的网络namespace",
      "if",
      "(clone_flags",
      "&",
      "CLONE_NEWNET)",
      "{",
      "p->nsproxy->net_ns",
      "=",
      "copy_net_ns(current->nsproxy->net_ns);",
      "}",
      "//",
      "...",
      "其他namespace的创建",
      "return",
      "p->pid;",
      "}",
      "**PID",
      "Namespace的实现（逐行解释）：**",
      "//",
      "kernel/pid_namespace.c",
      "//",
      "PID",
      "namespace结构体",
      "struct",
      "pid_namespace",
      "{",
      "struct",
      "kref",
      "kref;",
      "//",
      "引用计数",
      "struct",
      "idr",
      "idr;",
      "//",
      "PID分配器",
      "struct",
      "pid_namespace",
      "*parent;",
      "//",
      "父namespace",
      "int",
      "level;",
      "//",
      "层级（嵌套深度）",
      "struct",
      "task_struct",
      "*child_reaper;",
      "//",
      "init进程（PID",
      "1）",
      "};",
      "//",
      "创建新的PID",
      "namespace",
      "static",
      "struct",
      "pid_namespace",
      "*create_pid_namespace(struct",
      "pid_namespace",
      "*parent_ns)",
      "{",
      "struct",
      "pid_namespace",
      "*ns;",
      "//",
      "第1步：分配内存",
      "ns",
      "=",
      "kmalloc(sizeof(*ns),",
      "GFP_KERNEL);",
      "if",
      "(!ns)",
      "return",
      "ERR_PTR(-ENOMEM);",
      "//",
      "第2步：初始化PID分配器",
      "//",
      "IDR是内核的ID分配器，用于分配唯一的PID",
      "idr_init(&ns->idr);",
      "//",
      "第3步：设置父namespace和层级",
      "ns->parent",
      "=",
      "get_pid_ns(parent_ns);",
      "//",
      "增加父namespace引用计数",
      "ns->level",
      "=",
      "parent_ns->level",
      "+",
      "1;",
      "//",
      "层级+1",
      "//",
      "第4步：设置init进程（PID",
      "1）",
      "//",
      "容器内的第一个进程会成为init进程",
      "ns->child_reaper",
      "=",
      "current;",
      "return",
      "ns;",
      "}",
      "//",
      "在namespace中分配PID",
      "struct",
      "pid",
      "*alloc_pid(struct",
      "pid_namespace",
      "*ns)",
      "{",
      "struct",
      "pid",
      "*pid;",
      "int",
      "i,",
      "nr;",
      "//",
      "第1步：分配pid结构体",
      "pid",
      "=",
      "kmem_cache_alloc(pid_cachep,",
      "GFP_KERNEL);",
      "//",
      "第2步：在每一层namespace中分配PID",
      "//",
      "关键：一个进程在不同层级的namespace中有不同的PID！",
      "for",
      "(i",
      "=",
      "ns->level;",
      "i",
      ">=",
      "0;",
      "i--)",
      "{",
      "struct",
      "pid_namespace",
      "*tmp",
      "=",
      "ns;",
      "//",
      "在当前层级分配PID",
      "nr",
      "=",
      "idr_alloc(&tmp->idr,",
      "NULL,",
      "1,",
      "INT_MAX,",
      "GFP_KERNEL);",
      "//",
      "存储这一层的PID",
      "pid->numbers[i].nr",
      "=",
      "nr;",
      "pid->numbers[i].ns",
      "=",
      "tmp;",
      "//",
      "移动到父namespace",
      "tmp",
      "=",
      "tmp->parent;",
      "}",
      "return",
      "pid;",
      "}",
      "//",
      "查找进程（关键函数）",
      "struct",
      "task_struct",
      "*find_task_by_pid_ns(pid_t",
      "nr,",
      "struct",
      "pid_namespace",
      "*ns)",
      "{",
      "//",
      "只在指定的namespace中查找",
      "//",
      "这就是隔离的关键：不同namespace看到不同的进程列表",
      "return",
      "pid_task(find_pid_ns(nr,",
      "ns),",
      "PIDTYPE_PID);",
      "}",
      "**费曼解释（PID",
      "Namespace）：**",
      "PID",
      "Namespace就像平行宇宙：",
      "场景：容器内运行nginx进程",
      "宿主机视角：",
      "-",
      "ps",
      "aux",
      "|",
      "grep",
      "nginx",
      "-",
      "PID",
      "12345",
      "nginx",
      "容器内视角：",
      "-",
      "ps",
      "aux",
      "|",
      "grep",
      "nginx",
      "-",
      "PID",
      "1",
      "nginx",
      "同一个进程，在不同namespace中有不同的PID！",
      "实现原理：",
      "1.",
      "每个namespace有自己的PID分配器（IDR）",
      "2.",
      "进程在每一层namespace都有一个PID",
      "3.",
      "查找进程时，只在当前namespace中查找",
      "4.",
      "容器内看不到宿主机的进程（隔离）",
      "类比：",
      "-",
      "宿主机",
      "=",
      "地球",
      "-",
      "容器",
      "=",
      "火星基地",
      "-",
      "同一个人，在地球叫\"张三\"，在火星叫\"1号\"",
      "-",
      "火星上的人看不到地球上的人（隔离）",
      "第三步：Cgroup源码分析（资源限制）",
      "**Cgroup的层级结构：**",
      "#",
      "Cgroup文件系统（cgroupfs）",
      "/sys/fs/cgroup/",
      "├──",
      "cpu/",
      "#",
      "CPU控制器",
      "│",
      "├──",
      "docker/",
      "│",
      "│",
      "└──",
      "<container_id>/",
      "│",
      "│",
      "├──",
      "cpu.cfs_quota_us",
      "#",
      "CPU配额",
      "│",
      "│",
      "├──",
      "cpu.cfs_period_us",
      "#",
      "配额周期",
      "│",
      "│",
      "└──",
      "tasks",
      "#",
      "进程列表",
      "├──",
      "memory/",
      "#",
      "内存控制器",
      "│",
      "├──",
      "docker/",
      "│",
      "│",
      "└──",
      "<container_id>/",
      "│",
      "│",
      "├──",
      "memory.limit_in_bytes",
      "#",
      "内存限制",
      "│",
      "│",
      "├──",
      "memory.usage_in_bytes",
      "#",
      "当前使用",
      "│",
      "│",
      "└──",
      "tasks",
      "└──",
      "blkio/",
      "#",
      "磁盘IO控制器",
      "└──",
      "...",
      "**CPU限制的实现（CFS调度器）：**",
      "//",
      "kernel/sched/fair.c",
      "//",
      "CFS（完全公平调度器）的Cgroup结构",
      "struct",
      "task_group",
      "{",
      "struct",
      "cfs_bandwidth",
      "cfs_bandwidth;",
      "//",
      "CPU带宽控制",
      "};",
      "struct",
      "cfs_bandwidth",
      "{",
      "raw_spinlock_t",
      "lock;",
      "ktime_t",
      "period;",
      "//",
      "周期（默认100ms）",
      "u64",
      "quota;",
      "//",
      "配额（例如50ms",
      "=",
      "50%",
      "CPU）",
      "u64",
      "runtime;",
      "//",
      "剩余运行时间",
      "s64",
      "hierarchical_quota;",
      "//",
      "层级配额",
      "struct",
      "hrtimer",
      "period_timer;",
      "//",
      "周期定时器",
      "};",
      "//",
      "检查是否超过CPU配额",
      "static",
      "int",
      "throttle_cfs_rq(struct",
      "cfs_rq",
      "*cfs_rq)",
      "{",
      "struct",
      "task_group",
      "*tg",
      "=",
      "cfs_rq->tg;",
      "struct",
      "cfs_bandwidth",
      "*cfs_b",
      "=",
      "&tg->cfs_bandwidth;",
      "//",
      "第1步：检查剩余运行时间",
      "if",
      "(cfs_rq->runtime_remaining",
      "<=",
      "0)",
      "{",
      "//",
      "配额用完了！",
      "//",
      "第2步：从队列中移除所有任务",
      "//",
      "这些任务将无法被调度，直到下个周期",
      "dequeue_task(cfs_rq);",
      "//",
      "第3步：设置throttled标志",
      "cfs_rq->throttled",
      "=",
      "1;",
      "return",
      "1;",
      "//",
      "已限流",
      "}",
      "return",
      "0;",
      "//",
      "未限流",
      "}",
      "//",
      "周期定时器回调（每100ms触发一次）",
      "static",
      "enum",
      "hrtimer_restart",
      "sched_cfs_period_timer(struct",
      "hrtimer",
      "*timer)",
      "{",
      "struct",
      "cfs_bandwidth",
      "*cfs_b",
      "=",
      "container_of(timer,",
      "struct",
      "cfs_bandwidth,",
      "period_timer);",
      "//",
      "第1步：重置配额",
      "//",
      "例如：quota",
      "=",
      "50ms（50%",
      "CPU）",
      "cfs_b->runtime",
      "=",
      "cfs_b->quota;",
      "//",
      "第2步：唤醒被限流的任务",
      "//",
      "新的周期开始，可以继续运行了",
      "unthrottle_cfs_rq(cfs_b);",
      "//",
      "第3步：重新启动定时器（下个周期）",
      "hrtimer_forward_now(timer,",
      "cfs_b->period);",
      "return",
      "HRTIMER_RESTART;",
      "}",
      "**费曼解释（CPU",
      "Cgroup）：**",
      "CPU",
      "Cgroup就像限速器：",
      "场景：容器限制为50%",
      "CPU",
      "配置：",
      "-",
      "cpu.cfs_period_us",
      "=",
      "100000",
      "#",
      "周期100ms",
      "-",
      "cpu.cfs_quota_us",
      "=",
      "50000",
      "#",
      "配额50ms",
      "工作原理：",
      "1.",
      "每100ms一个周期",
      "2.",
      "容器在这100ms内最多运行50ms",
      "3.",
      "运行50ms后，被强制暂停",
      "4.",
      "等待下个周期（再过50ms）",
      "5.",
      "新周期开始，又可以运行50ms",
      "类比：",
      "-",
      "周期",
      "=",
      "1小时",
      "-",
      "配额",
      "=",
      "30分钟",
      "-",
      "你每小时只能工作30分钟",
      "-",
      "工作30分钟后，必须休息30分钟",
      "-",
      "下一小时开始，又可以工作30分钟",
      "结果：",
      "-",
      "平均CPU使用率",
      "=",
      "50ms",
      "/",
      "100ms",
      "=",
      "50%",
      "-",
      "即使容器想用100%",
      "CPU，也被限制在50%",
