      "时间：10亿次操作",
      "/",
      "(4GHz",
      "×",
      "6912)",
      "≈",
      "0.036毫秒",
      "#",
      "快了7000倍！",
      "**CUDA编程模型：**",
      "//",
      "1.",
      "定义kernel（在GPU上运行的函数）",
      "__global__",
      "void",
      "matrixMul(float",
      "*A,",
      "float",
      "*B,",
      "float",
      "*C,",
      "int",
      "N)",
      "{",
      "//",
