      "(row",
      "<",
      "N",
      "&&",
      "col",
      "<",
      "N)",
      "{",
      "float",
      "sum",
      "=",
      "0;",
      "for",
      "(int",
      "k",
      "=",
      "0;",
      "k",
      "<",
      "N;",
      "k++)",
