      "sum",
      "+=",
      "A[row",
      "*",
      "N",
      "+",
      "k]",
      "*",
      "B[k",
      "*",
      "N",
      "+",
      "col];",
      "}",
      "C[row",
      "*",
      "N",
      "+",
      "col]",
