      "}",
      "}",
      "//",
      "2.",
      "主机代码",
      "int",
      "main()",
      "{",
      "//",
      "分配GPU内存",
      "float",
      "*d_A,",
      "*d_B,",
      "*d_C;",
      "cudaMalloc(&d_A,",
      "size);",
      "cudaMalloc(&d_B,",
      "size);",
      "cudaMalloc(&d_C,",
      "size);",
      "//",
      "拷贝数据到GPU",
      "cudaMemcpy(d_A,",
